PSP_MODULE_INFO("PSPulseGame", PSP_MODULE_USER, 1, 1);
PSP_MAIN_THREAD_ATTR(THREAD_ATTR_USER | THREAD_ATTR_VFPU);
PSP_HEAP_SIZE_KB(12 * 1024);

using namespace pspruntime;

namespace {

// --------------------------------------------------------------------------
// Constants / display
// --------------------------------------------------------------------------
// Sizes/addresses follow the PSPSDK GU samples (cube/font): the GE requires a
// 16-byte aligned, offset-free command buffer and separate aligned buffers for
// the depth and drawing areas.
constexpr int kScreenWidth = 480;
constexpr int kScreenHeight = 272;
constexpr int kBufWidth = 512;
constexpr int kScrWidth = 480;
constexpr int kScrHeight = 272;
constexpr unsigned int kFbp0 = 0;
constexpr unsigned int kFbp1 = kFbp0 + kBufWidth * kScrHeight * 4;
constexpr unsigned int kZbp = kFbp1 + kBufWidth * kScrHeight * 4;

unsigned int __attribute__((aligned(16))) gDispList[262144];

// --------------------------------------------------------------------------
// Runtime state
// --------------------------------------------------------------------------
struct RuntimeState {
    Scene scene;
    Physics physics;
    RuntimeLua lua;
    PadState pad;
    PadState previousPad;
    bool running = true;
    bool showDebug = false;
    bool scriptsEnabled = false;
    float time = 0.0f;
    float fps = 0.0f;
    int frameCount = 0;
    float fpsTimer = 0.0f;
    int cameraIndex = -1;
    Vec3 cameraFollowTarget;
    std::string consoleLines[8];
    int consoleCount = 0;
    std::string status = "OK";
} gState;

// --------------------------------------------------------------------------
// Kernel callbacks
// --------------------------------------------------------------------------
int ExitCallback(int, int, void*) {
    gState.running = false;
    sceKernelExitGame();
    return 0;
}

int CallbackThread(SceSize, void*) {
    int callbackId = sceKernelCreateCallback("ExitCallback", ExitCallback, nullptr);
    sceKernelRegisterExitCallback(callbackId);
    sceKernelSleepThreadCB();
    return 0;
}

void SetupCallbacks() {
    int threadId = sceKernelCreateThread("update_thread", CallbackThread, 0x11, 0xFA0, 0, 0);
    if (threadId >= 0) sceKernelStartThread(threadId, 0, nullptr);
}

// --------------------------------------------------------------------------
// Utility
// --------------------------------------------------------------------------
unsigned int ColorRGBA(float r, float g, float b, float a = 1.0f) {
    auto clamp = [](float v) {
        if (v < 0.0f) v = 0.0f;
        if (v > 1.0f) v = 1.0f;
        return static_cast<unsigned int>(v * 255.0f + 0.5f);
    };
    return clamp(r) | (clamp(g) << 8) | (clamp(b) << 16) | (clamp(a) << 24);
}

// --------------------------------------------------------------------------
// Text rendering through GU (8x8 bitmap font, point sprites)
// --------------------------------------------------------------------------
struct TextVertex {
    unsigned int color;
    float x, y, z;
};

namespace {

int GlyphQuadCount(const unsigned char* glyph) {
    int count = 0;
    for (int row = 0; row < 8; ++row) {
        unsigned int bits = glyph[row];
        while (bits) {
            count += static_cast<int>(bits & 1u);
            bits >>= 1;
        }
    }
    return count;
}

} // namespace

// GU_TRANSFORM_2D still runs vertices through the GUM projection/view/model
// matrices, so every 2D batch must reset all three to identity or pixel-space
// quads get projected by the 3D camera (classic "streaks across the screen").
void ResetGumTo2D() {
    sceGumMatrixMode(GU_PROJECTION);
    sceGumLoadIdentity();
    sceGumMatrixMode(GU_VIEW);
    sceGumLoadIdentity();
    sceGumMatrixMode(GU_MODEL);
    sceGumLoadIdentity();
}

void DrawText(int x, int y, const char* text, unsigned int color) {
    sceGuDisable(GU_DEPTH_TEST);
    sceGuDisable(GU_TEXTURE_2D);
    sceGuDisable(GU_CULL_FACE);
    sceGuDisable(GU_LIGHTING);

    // Pass 1: count lit pixels so the exact amount of display-list memory is
    // reserved (a fixed-size reservation overflows the list and corrupts the
    // command stream).
    int quadCount = 0;
    for (const char* c = text; *c; ++c) {
        if (*c == ' ') continue;
        quadCount += GlyphQuadCount(Glyph(*c));
    }
    if (quadCount == 0) {
        sceGuEnable(GU_DEPTH_TEST);
        sceGuEnable(GU_CULL_FACE);
        return;
    }

    TextVertex* vertices =
        static_cast<TextVertex*>(sceGuGetMemory(sizeof(TextVertex) * 6 * quadCount));
    if (!vertices) {
        sceGuEnable(GU_DEPTH_TEST);
        sceGuEnable(GU_CULL_FACE);
        return;
    }

    int index = 0;
    int cursorX = x;
    for (const char* c = text; *c; ++c) {
        if (*c == ' ') {
            cursorX += 5;
            continue;
        }
        const unsigned char* glyph = Glyph(*c);
        for (int row = 0; row < 8; ++row) {
            for (int col = 0; col < 8; ++col) {
                // Standard 8x8 layout: bit 7 (MSB) is the leftmost pixel.
                if (!(glyph[row] & (0x80 >> col))) continue;
                const float px = static_cast<float>(cursorX + col);
                const float py = static_cast<float>(y + row);
                TextVertex* v = &vertices[index * 6];
                v[0] = {color, px, py, 0.0f};
                v[1] = {color, px + 1.0f, py, 0.0f};
                v[2] = {color, px + 1.0f, py + 1.0f, 0.0f};
                v[3] = {color, px, py, 0.0f};
                v[4] = {color, px + 1.0f, py + 1.0f, 0.0f};
                v[5] = {color, px, py + 1.0f, 0.0f};
                ++index;
            }
        }
        cursorX += 6;
    }

    ResetGumTo2D();
    sceGumDrawArray(GU_TRIANGLES, GU_COLOR_8888 | GU_VERTEX_32BITF | GU_TRANSFORM_2D, index * 6,
                    nullptr, vertices);
    sceGuEnable(GU_DEPTH_TEST);
    sceGuEnable(GU_CULL_FACE);
}

void DrawRect(int x, int y, int width, int height, unsigned int colorTop, unsigned int colorBottom) {
    sceGuDisable(GU_DEPTH_TEST);
    sceGuDisable(GU_CULL_FACE);
    sceGuDisable(GU_LIGHTING);
    TextVertex* vertices = static_cast<TextVertex*>(sceGuGetMemory(sizeof(TextVertex) * 6));
    float x0 = static_cast<float>(x), y0 = static_cast<float>(y);
    float x1 = static_cast<float>(x + width), y1 = static_cast<float>(y + height);
    vertices[0] = {colorTop, x0, y0, 0.0f};
    vertices[1] = {colorTop, x1, y0, 0.0f};
    vertices[2] = {colorBottom, x1, y1, 0.0f};
    vertices[3] = {colorTop, x0, y0, 0.0f};
    vertices[4] = {colorBottom, x1, y1, 0.0f};
    vertices[5] = {colorBottom, x0, y1, 0.0f};
    ResetGumTo2D();
    sceGumDrawArray(GU_TRIANGLES, GU_COLOR_8888 | GU_VERTEX_32BITF | GU_TRANSFORM_2D, 6, nullptr,
                    vertices);
    sceGuEnable(GU_DEPTH_TEST);
    sceGuEnable(GU_CULL_FACE);
}

// --------------------------------------------------------------------------
// Input
// --------------------------------------------------------------------------
void ReadPad(PadState& pad, const PadState& previous) {
    SceCtrlData data;
    std::memset(&data, 0, sizeof(data));
    sceCtrlPeekBufferPositive(&data, 1);

    unsigned int buttons = data.Buttons;
    unsigned int previousButtons = previous.cross ? PSP_CTRL_CROSS : 0;
    // Build "previous" mask from our own state for accurate edge detection.
    previousButtons = 0;
    if (previous.up) previousButtons |= PSP_CTRL_UP;
    if (previous.down) previousButtons |= PSP_CTRL_DOWN;
    if (previous.left) previousButtons |= PSP_CTRL_LEFT;
    if (previous.right) previousButtons |= PSP_CTRL_RIGHT;
    if (previous.cross) previousButtons |= PSP_CTRL_CROSS;
    if (previous.circle) previousButtons |= PSP_CTRL_CIRCLE;
    if (previous.square) previousButtons |= PSP_CTRL_SQUARE;
    if (previous.triangle) previousButtons |= PSP_CTRL_TRIANGLE;
    if (previous.lTrigger) previousButtons |= PSP_CTRL_LTRIGGER;
    if (previous.rTrigger) previousButtons |= PSP_CTRL_RTRIGGER;
    if (previous.start) previousButtons |= PSP_CTRL_START;
    if (previous.select) previousButtons |= PSP_CTRL_SELECT;

    unsigned int pressed = buttons & ~previousButtons;

    pad.up = (buttons & PSP_CTRL_UP) != 0;
    pad.down = (buttons & PSP_CTRL_DOWN) != 0;
    pad.left = (buttons & PSP_CTRL_LEFT) != 0;
    pad.right = (buttons & PSP_CTRL_RIGHT) != 0;
    pad.cross = (buttons & PSP_CTRL_CROSS) != 0;
    pad.circle = (buttons & PSP_CTRL_CIRCLE) != 0;
    pad.square = (buttons & PSP_CTRL_SQUARE) != 0;
    pad.triangle = (buttons & PSP_CTRL_TRIANGLE) != 0;
    pad.lTrigger = (buttons & PSP_CTRL_LTRIGGER) != 0;
    pad.rTrigger = (buttons & PSP_CTRL_RTRIGGER) != 0;
    pad.start = (buttons & PSP_CTRL_START) != 0;
    pad.select = (buttons & PSP_CTRL_SELECT) != 0;

    pad.crossPressed = (pressed & PSP_CTRL_CROSS) != 0;
    pad.circlePressed = (pressed & PSP_CTRL_CIRCLE) != 0;
    pad.startPressed = (pressed & PSP_CTRL_START) != 0;
    pad.selectPressed = (pressed & PSP_CTRL_SELECT) != 0;
    pad.lTriggerPressed = (pressed & PSP_CTRL_LTRIGGER) != 0;
    pad.rTriggerPressed = (pressed & PSP_CTRL_RTRIGGER) != 0;

    // Analog nub / d-pad emulation: -1..1.
    float ax = (static_cast<float>(data.Lx) - 128.0f) / 127.0f;
    float ay = (static_cast<float>(data.Ly) - 128.0f) / 127.0f;
    if (std::fabs(ax) < 0.18f) ax = 0.0f;
    if (std::fabs(ay) < 0.18f) ay = 0.0f;
    if (pad.left) ax = -1.0f;
    if (pad.right) ax = 1.0f;
    if (pad.up) ay = -1.0f;
    if (pad.down) ay = 1.0f;
    pad.analogX = ax;
    pad.analogY = ay;
}

// --------------------------------------------------------------------------
// Console & script loading
// --------------------------------------------------------------------------
void AddConsoleLine(const std::string& line) {
    if (gState.consoleCount < 8) {
        gState.consoleLines[gState.consoleCount++] = line;
    } else {
        for (int i = 1; i < 8; ++i) gState.consoleLines[i - 1] = gState.consoleLines[i];
        gState.consoleLines[7] = line;
    }
}

// --------------------------------------------------------------------------
// Scene setup
// --------------------------------------------------------------------------
bool LoadEmbeddedScene();

void LoadSceneScripts() {
    if (!gState.scriptsEnabled) return;
    std::string error;
    int loaded = 0;

    for (auto& object : gState.scene.objects) {
        if (object.script.empty()) continue;
        std::string source;
        if (gPspAssetBundle.startupLuaSize > 0 &&
            object.script == std::string(gPspAssetBundle.startupScriptPath ? gPspAssetBundle.startupScriptPath : "")) {
            source.assign(reinterpret_cast<const char*>(gPspAssetBundle.startupLua),
                          static_cast<size_t>(gPspAssetBundle.startupLuaSize));
        }
        // Scripts bundled by the editor build (see generated_assets.cpp).
        if (source.empty()) {
            for (unsigned int i = 0; i < gPspScriptCount; ++i) {
                const PspScriptEntry& entry = gPspScriptTable[i];
                if (entry.path && object.script == std::string(entry.path)) {
                    source.assign(reinterpret_cast<const char*>(entry.data),
                                  static_cast<size_t>(entry.size));
                    break;
                }
            }
        }
        if (source.empty()) {
            // Fallback demo behaviour when the script source was not packed
            // into the EBOOT (e.g. scene references a file outside the build).
            source =
                "function on_update(dt)\n"
                "  local rx, ry, rz = rotation()\n"
                "  set_rotation(rx, ry + dt * 40, rz)\n"
                "end\n";
        }
        if (gState.lua.LoadScript(gState.scene, object.id, source, object.script, error)) {
            ++loaded;
        } else {
            AddConsoleLine("script error: " + error);
        }
    }
    char buffer[64];
    std::snprintf(buffer, sizeof(buffer), "Lua scripts loaded: %d", loaded);
    AddConsoleLine(buffer);
}

void ResetScene() {
    gState.lua.ClearScripts();
    if (LoadEmbeddedScene()) LoadSceneScripts();
}

bool LoadEmbeddedScene() {
    gState.scene = Scene();
    gState.lua.SetScene(gState.scene);
    std::string json(reinterpret_cast<const char*>(gPspAssetBundle.sceneJson),
                     static_cast<size_t>(gPspAssetBundle.sceneJsonSize));
    std::string error;
    if (!ParseScene(json, gState.scene, error)) {
        AddConsoleLine("scene error: " + error);
        return false;
    }
    gState.scene.UpdateWorldMatrices();
    gState.physics.Sync(gState.scene);

    // Find the active camera.
    for (size_t i = 0; i < gState.scene.objects.size(); ++i) {
        if (gState.scene.objects[i].camera.enabled) {
            gState.cameraIndex = static_cast<int>(i);
            break;
        }
    }
    if (gState.cameraIndex >= 0) {
        gState.cameraFollowTarget = gState.scene.objects[gState.cameraIndex].transform.position;
    } else {
        gState.cameraFollowTarget = Vec3(0.0f, 2.0f, 0.0f);
    }
    char buffer[96];
    std::snprintf(buffer, sizeof(buffer), "Scene '%s': %d objects", gState.scene.name.c_str(),
                  static_cast<int>(gState.scene.objects.size()));
    AddConsoleLine(buffer);
    return true;
}

// --------------------------------------------------------------------------
// Rendering
// --------------------------------------------------------------------------
// --------------------------------------------------------------------------
// Embedded glTF models
// --------------------------------------------------------------------------
// The editor packs every assets/**.gltf|glb into generated_assets.cpp as
// gPspMeshTable. Meshes are parsed lazily, once per path, and cached in RAM
// (a PSP has 28 MB of usable user memory, so models are kept small).
struct ModelCacheEntry {
    std::string path;
    GltfMeshData mesh;
    bool valid = false;
};
static constexpr int kMaxModels = 12;
static ModelCacheEntry gModelCache[kMaxModels];
static int gModelCacheCount = 0;

static const GltfMeshData* GetModelMesh(const std::string& path) {
    if (path.empty()) return nullptr;
    for (int i = 0; i < gModelCacheCount; ++i) {
        if (gModelCache[i].path == path) return gModelCache[i].valid ? &gModelCache[i].mesh : nullptr;
    }
    if (gModelCacheCount >= kMaxModels) return nullptr;

    ModelCacheEntry& entry = gModelCache[gModelCacheCount];
    entry.path = path;
    entry.valid = false;
    ++gModelCacheCount;

    for (unsigned int i = 0; i < gPspMeshCount; ++i) {
        const PspMeshEntry& packed = gPspMeshTable[i];
        if (!packed.path || path != packed.path) continue;
        GltfMeshData& mesh = entry.mesh;
        std::string error;
        if (!LoadGltfMeshToGltfData(packed.data, packed.size, path.c_str(), mesh, error)) {
            char buffer[128];
            std::snprintf(buffer, sizeof(buffer), "model error: %.100s", error.c_str());
            AddConsoleLine(buffer);
            return nullptr;
        }
        entry.valid = true;
        return &entry.mesh;
    }
    AddConsoleLine("model not packed: " + path);
    return nullptr;
}

void DrawScene() {
    // The GE only performs hardware lighting when per-vertex normals are
    // supplied (GU_NORMAL_32BITF). Our procedural meshes carry baked vertex
    // colours instead, which is the cheapest and most predictable path on the
    // PSP, so lighting stays disabled for the 3D pass.
    sceGuDisable(GU_LIGHTING);
    sceGuDisable(GU_CULL_FACE);

    sceGumMatrixMode(GU_PROJECTION);
    sceGumLoadIdentity();
    const float fov = gState.cameraIndex >= 0 ? gState.scene.objects[gState.cameraIndex].camera.fov : 60.0f;
    sceGumPerspective(fov, static_cast<float>(kScreenWidth) / kScreenHeight, 0.5f, 200.0f);

    sceGumMatrixMode(GU_VIEW);
    sceGumLoadIdentity();
    {
        ScePspFVector3 eye{gState.cameraFollowTarget.x + 10.0f,
                           gState.cameraFollowTarget.y + 7.0f,
                           gState.cameraFollowTarget.z + 12.0f};
        ScePspFVector3 center{gState.cameraFollowTarget.x, gState.cameraFollowTarget.y,
                              gState.cameraFollowTarget.z};
        ScePspFVector3 up{0.0f, 1.0f, 0.0f};
        sceGumLookAt(&eye, &center, &up);
    }
    sceGumUpdateMatrix();
    sceGumMatrixMode(GU_MODEL);

    for (const auto& object : gState.scene.objects) {
        if (!object.visible) continue;
        // A glTF reference wins over the primitive; a missing/broken model is
        // reported to the console instead of taking the frame down.
        if (!object.meshPath.empty()) {
            const GltfMeshData* model = GetModelMesh(object.meshPath);
            if (!model || model->positions.empty()) continue;

            sceGumLoadIdentity();
            {
                ScePspFVector3 t{object.transform.position.x, object.transform.position.y,
                                 object.transform.position.z};
                sceGumTranslate(&t);
            }
            {
                ScePspFVector3 r{object.transform.rotation.x * 0.0174532925f,
                                 object.transform.rotation.y * 0.0174532925f,
                                 object.transform.rotation.z * 0.0174532925f};
                sceGumRotateXYZ(&r);
            }
            {
                ScePspFVector3 s{object.transform.scale.x, object.transform.scale.y,
                                 object.transform.scale.z};
                sceGumScale(&s);
            }
            sceGumUpdateMatrix();

            const unsigned int tint = ColorRGBA(object.color[0], object.color[1], object.color[2], 1.0f);
            Mesh modelMesh;
            BuildMeshFromGltf(*model, tint, modelMesh);
            if (modelMesh.vertices.empty()) continue;

            const unsigned int byteSize =
                static_cast<unsigned int>(modelMesh.vertices.size() * sizeof(MeshVertex));
            void* vertices = sceGuGetMemory(static_cast<int>(byteSize));
            if (!vertices) continue;
            std::memcpy(vertices, modelMesh.vertices.data(), byteSize);
            sceGumDrawArray(GU_TRIANGLES, GU_COLOR_8888 | GU_VERTEX_32BITF | GU_TRANSFORM_3D,
                            static_cast<int>(modelMesh.vertices.size()), nullptr, vertices);
            continue;
        }
        if (object.primitive == PrimEmpty) continue;

        sceGumLoadIdentity();
        {
            ScePspFVector3 t{object.transform.position.x, object.transform.position.y,
                             object.transform.position.z};
            sceGumTranslate(&t);
        }
        {
            ScePspFVector3 r{object.transform.rotation.x * 0.0174532925f,
                             object.transform.rotation.y * 0.0174532925f,
                             object.transform.rotation.z * 0.0174532925f};
            sceGumRotateXYZ(&r);
        }
        {
            ScePspFVector3 s{object.transform.scale.x, object.transform.scale.y,
                             object.transform.scale.z};
            sceGumScale(&s);
        }
        sceGumUpdateMatrix();

        // Bake a simple top-light into the vertex colours so the scene reads
        // three-dimensionally without per-vertex normals.
        const float lighting = 0.75f + 0.25f * (object.transform.rotation.x < 0.0f ? 0.4f : 1.0f);
        const unsigned int color = ColorRGBA(object.color[0] * lighting * 1.15f,
                                             object.color[1] * lighting * 1.15f,
                                             object.color[2] * lighting * 1.15f, 1.0f);

        Mesh mesh;
        BuildPrimitiveMesh(object.primitive, color, mesh);
        if (mesh.vertices.empty()) continue;

        const unsigned int byteSize = static_cast<unsigned int>(mesh.vertices.size() * sizeof(MeshVertex));
        void* vertices = sceGuGetMemory(static_cast<int>(byteSize));
        if (!vertices) continue;
        std::memcpy(vertices, mesh.vertices.data(), byteSize);
        sceGumDrawArray(GU_TRIANGLES, GU_COLOR_8888 | GU_VERTEX_32BITF | GU_TRANSFORM_3D,
                        static_cast<int>(mesh.vertices.size()), nullptr, vertices);
    }

    sceGuEnable(GU_CULL_FACE);
}

void DrawGrid() {
    constexpr int kGridHalf = 10;
    constexpr float kCell = 1.0f;
    constexpr int kLineCount = (kGridHalf * 2 + 1) * 2;
    TextVertex* vertices = static_cast<TextVertex*>(sceGuGetMemory(sizeof(TextVertex) * kLineCount * 2));
    int index = 0;
    unsigned int color = ColorRGBA(0.30f, 0.33f, 0.40f);
    unsigned int axisX = ColorRGBA(0.55f, 0.22f, 0.24f);
    unsigned int axisZ = ColorRGBA(0.20f, 0.34f, 0.62f);
    // Lift the grid a hair above y=0 so it does not z-fight with the ground plane.
    constexpr float kGridY = 0.02f;
    for (int i = -kGridHalf; i <= kGridHalf; ++i) {
        float p = static_cast<float>(i) * kCell;
        vertices[index++] = {i == 0 ? axisZ : color, p, kGridY, -kGridHalf * kCell};
        vertices[index++] = {i == 0 ? axisZ : color, p, kGridY, kGridHalf * kCell};
        vertices[index++] = {i == 0 ? axisX : color, -kGridHalf * kCell, kGridY, p};
        vertices[index++] = {i == 0 ? axisX : color, kGridHalf * kCell, kGridY, p};
    }
    sceGumLoadIdentity();
    sceGumUpdateMatrix();
    sceGuDisable(GU_LIGHTING);
    sceGuDisable(GU_CULL_FACE);
    sceGumDrawArray(GU_LINES, GU_COLOR_8888 | GU_VERTEX_32BITF | GU_TRANSFORM_3D, index, nullptr,
                    vertices);
    sceGuEnable(GU_CULL_FACE);
}

void DrawHud() {
    sceGuDisable(GU_DEPTH_TEST);
    sceGuDisable(GU_LIGHTING);
    sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD, GU_SRC_ALPHA, GU_ONE_MINUS_SRC_ALPHA, 0, 0);

    char line[128];
    const char* title = gPspAssetBundle.title ? gPspAssetBundle.title : "PSPulse";
    std::snprintf(line, sizeof(line), "%s", title);
    DrawText(8, 6, "PSP ENGINE RUNTIME", ColorRGBA(0.55f, 0.85f, 1.0f));
    DrawText(8, 16, line, ColorRGBA(1.0f, 1.0f, 1.0f));

    std::snprintf(line, sizeof(line), "FPS %3.0f  OBJ %d  LUA %d", gState.fps,
                  static_cast<int>(gState.scene.objects.size()), gState.lua.ScriptCount());
    DrawText(8, 30, line, ColorRGBA(0.75f, 0.8f, 0.85f));

    // Last few Lua prints are always shown so scripting is visible in-game.
    {
        const auto& messages = gState.lua.Messages();
        int shown = 0;
        int y = kScreenHeight - 28;
        for (int i = static_cast<int>(messages.size()) - 1; i >= 0 && shown < 3; --i, ++shown) {
            DrawText(8, y, messages[static_cast<size_t>(i)].c_str(),
                     ColorRGBA(0.60f, 0.95f, 0.70f, 0.9f));
            y -= 12;
        }
    }

    if (gState.showDebug) {
        DrawRect(4, 48, 320, 8 + 12 * (gState.consoleCount + 2), ColorRGBA(0.05f, 0.07f, 0.1f, 0.85f),
                 ColorRGBA(0.02f, 0.03f, 0.05f, 0.85f));
        DrawText(10, 52, "CONSOLE (SELECT+LTOGGLE)", ColorRGBA(0.6f, 0.9f, 0.7f));
        int y = 66;
        for (int i = 0; i < gState.consoleCount; ++i) {
            DrawText(10, y, gState.consoleLines[i].c_str(), ColorRGBA(0.85f, 0.9f, 0.95f));
            y += 10;
        }
        char physicsLine[96];
        std::snprintf(physicsLine, sizeof(physicsLine), "colliders: %d  status: %s",
                      gState.physics.ColliderCount(), gState.status.c_str());
        DrawText(10, y, physicsLine, ColorRGBA(0.7f, 0.75f, 0.8f));
    } else {
        DrawText(8, kScreenHeight - 14, "SELECT+SLCT: debug  |  nub/dpad: drive", 
                 ColorRGBA(0.65f, 0.70f, 0.78f));
    }

    sceGuDisable(GU_BLEND);
    sceGuEnable(GU_DEPTH_TEST);
    sceGuEnable(GU_CULL_FACE);
}

// --------------------------------------------------------------------------
// Main
// --------------------------------------------------------------------------
void InitGu() {
    sceGuInit();

    sceGuStart(GU_DIRECT, gDispList);
    sceGuDrawBuffer(GU_PSM_8888, reinterpret_cast<void*>(static_cast<uintptr_t>(kFbp0)), kBufWidth);
    sceGuDispBuffer(kScrWidth, kScrHeight, reinterpret_cast<void*>(static_cast<uintptr_t>(kFbp1)),
                    kBufWidth);
    sceGuDepthBuffer(reinterpret_cast<void*>(static_cast<uintptr_t>(kZbp)), kBufWidth);
    sceGuOffset(2048 - (kScrWidth / 2), 2048 - (kScrHeight / 2));
    sceGuViewport(2048, 2048, kScrWidth, kScrHeight);
    sceGuDepthRange(65535, 0);
    sceGuScissor(0, 0, kScrWidth, kScrHeight);
    sceGuEnable(GU_SCISSOR_TEST);
    sceGuDepthFunc(GU_GEQUAL);
    sceGuEnable(GU_DEPTH_TEST);
    sceGuFrontFace(GU_CW);
    sceGuEnable(GU_CULL_FACE);
    sceGuShadeModel(GU_SMOOTH);
    sceGuEnable(GU_CLIP_PLANES);
    sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD, GU_SRC_ALPHA, GU_ONE_MINUS_SRC_ALPHA, 0, 0);
    sceGuFinish();
    sceGuSync(GU_SYNC_FINISH, GU_SYNC_WHAT_DONE);
}

void MainLoop() {
    uint32_t tick = sceKernelGetSystemTimeLow();

    while (gState.running) {
        uint32_t now = sceKernelGetSystemTimeLow();
        float dt = static_cast<float>(now - tick) * 0.000001f;
        tick = now;
        if (dt > 0.1f) dt = 0.1f;
        gState.time += dt;

        ReadPad(gState.pad, gState.previousPad);

        if (gState.pad.select && gState.pad.lTrigger && !gState.previousPad.lTrigger) {
            gState.showDebug = !gState.showDebug;
        }
        if (gState.pad.startPressed) {
            AddConsoleLine("START pressed - resetting scene");
            ResetScene();
        }

        gState.lua.SetPad(gState.pad);

        // ---- update -------------------------------------------------------
        gState.physics.Step(gState.scene, dt);
        gState.lua.UpdateAll(gState.scene, dt);
        gState.scene.UpdateWorldMatrices();

        // Camera softly follows the highest dynamic object.
        if (gState.cameraIndex >= 0) {
            Vec3& cameraPos = gState.scene.objects[gState.cameraIndex].transform.position;
            cameraPos += (gState.cameraFollowTarget - cameraPos) * (dt * 2.0f);
        }

        gState.frameCount++;
        gState.fpsTimer += dt;
        if (gState.fpsTimer >= 0.5f) {
            gState.fps = gState.frameCount / gState.fpsTimer;
            gState.frameCount = 0;
            gState.fpsTimer = 0.0f;
        }

        // ---- render -------------------------------------------------------
        sceGuStart(GU_DIRECT, gDispList);
        sceGuClearColor(ColorRGBA(0.07f, 0.09f, 0.13f));
        sceGuClearDepth(0);
        sceGuClear(GU_COLOR_BUFFER_BIT | GU_DEPTH_BUFFER_BIT);

        DrawScene();
        DrawGrid();
        DrawHud();

        sceGuFinish();
        sceGuSync(GU_SYNC_FINISH, GU_SYNC_WHAT_DONE);
        sceDisplayWaitVblankStart();
        sceGuSwapBuffers();

        gState.previousPad = gState.pad;
    }
}

} // namespace

int main(int, char**) {
    pspDebugScreenInit();
    SetupCallbacks();
    sceCtrlSetSamplingCycle(0);
    sceCtrlSetSamplingMode(PSP_CTRL_MODE_ANALOG);

    gState.running = true;
    gState.fps = 0.0f;
    gState.time = 0.0f;
    gState.cameraIndex = -1;
    gState.showDebug = false;
    gState.consoleCount = 0;

    bool sceneOk = LoadEmbeddedScene();
    if (!sceneOk) {
        gState.status = "SCENE ERROR";
    }

    if (gState.lua.Init()) {
        gState.scriptsEnabled = true;
        LoadSceneScripts();
    } else {
        gState.status = "LUA INIT FAILED";
    }

    InitGu();
    sceDisplayWaitVblankStart();
    sceGuDisplay(GU_TRUE);
    MainLoop();

    gState.lua.Shutdown();
    sceGuTerm();
    sceKernelExitGame();
    return 0;
}
